-host {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 10px;\n  border-radius: 12px;\n  background: rgba(15, 20, 35, 0.92);\n  border: 1px solid rgba(90, 170, 255, 0.24);\n}\n\n.stream-demo-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  font-size: 12px;\n}\n\n.stream-demo-badge {\n  border-radius: 999px;\n  padding: 3px 8px;\n  border: 1px solid transparent;\n  font-size: 11px;\n}\n\n.stream-demo-badge.is-stream {\n  background: rgba(95, 208, 255, 0.16);\n  border-color: rgba(95, 208, 255, 0.36);\n}\n\n.stream-demo-badge.is-done {\n  background: rgba(137, 255, 184, 0.16);\n  border-color: rgba(137, 255, 184, 0.36);\n}\n\n.stream-demo-raw {\n  margin: 0;\n  white-space: pre-wrap;\n  word-break: break-word;\n  font: inherit;\n  line-height: 1.5;\n}\n\n.stream-demo-html :deep(p) {\n  margin: 0 0 0.45em;\n}\n\n.stream-demo-foot {\n  font-size: 11px;\n  color: rgba(230, 236, 255, 0.68);\n}\n</style>\n"],"sourceRoot":""}]);
