import { mountStreamingMessages } from '@util/streaming';
import App from './App.vue';
import { isStreamDemoMessage } from '../../shared/message';
$(() => {
    const { unmount } = mountStreamingMessages(() => createApp(App), {
        host: 'div',
        filter: (_messageId, message) => isStreamDemoMessage(message),
        prefix: 'stream-demo-minimal',
    });
    $(window).on('pagehide', () => {
        unmount();
    });
});
